using UnityEngine;

namespace CustomFootTrails
{
    /// <summary>
    /// Footstep bursts whose EMITTERS follow the player's foot bones.
    /// Existing particles remain in world space and fade behind the character.
    /// Works with the FootTrailEffect prefabs generated by Custom Foot Trails V3/V4.
    /// </summary>
    [DisallowMultipleComponent]
    public class FootTrailController : MonoBehaviour
    {
        [Header("Foot Effects (prefabs or scene instances)")]
        [Tooltip("Prefab từ Project sẽ tự tạo một instance riêng cho chân trái khi chạy game.")]
        [SerializeField] private FootTrailEffect leftEffect;
        [Tooltip("Có thể dùng cùng prefab với chân trái; mỗi chân sẽ có instance riêng.")]
        [SerializeField] private FootTrailEffect rightEffect;

        [Header("Foot Bone Tracking - FIX for stationary emitters")]
        [Tooltip("Assign the animated left foot bone from the Player hierarchy.")]
        [SerializeField] private Transform leftFootBone;
        [Tooltip("Assign the animated right foot bone from the Player hierarchy.")]
        [SerializeField] private Transform rightFootBone;
        [Tooltip("For Humanoid rigs, fill missing foot references or replace ik_foot helpers with the animated Humanoid feet.")]
        [SerializeField] private bool autoFindHumanoidBones = true;
        [Tooltip("Move the two effect GameObjects to their corresponding animated foot every frame.")]
        [SerializeField] private bool followFootBones = true;
        [Tooltip("Offset in WORLD units, e.g. negative Y to reach the bottom of a foot bone.")]
        [SerializeField] private Vector3 leftFootWorldOffset = new Vector3(0f, -0.05f, 0f);
        [SerializeField] private Vector3 rightFootWorldOffset = new Vector3(0f, -0.05f, 0f);
        [Tooltip("Keep particle emitters upright even if the foot bones rotate during walking.")]
        [SerializeField] private bool keepEmittersUpright = true;

        [Header("Movement Detection")]
        [Tooltip("Player/root transform actually moving in WORLD space; leave empty to use this component's transform.")]
        [SerializeField] private Transform movementSource;
        [Tooltip("ON: emit based on distance traveled. OFF: call footstep methods from Animation Events.")]
        [SerializeField] private bool automaticFootsteps = true;
        [SerializeField, Min(0.05f)] private float metersPerStep = 0.55f;
        [SerializeField, Min(0f)] private float minimumSpeed = 0.15f;
        [SerializeField, Min(1)] private int maximumStepsPerFrame = 2;
        [SerializeField, Min(0.1f)] private float teleportThreshold = 2f;

        [Header("Optional Ground Contact")]
        [Tooltip("Leave OFF while testing. Enable only with a ground-only layer mask.")]
        [SerializeField] private bool requireGroundContact = false;
        [SerializeField] private LayerMask groundLayers = ~0;
        [SerializeField, Min(0f)] private float probeStartAboveFoot = 0.35f;
        [SerializeField, Min(0.05f)] private float probeDistanceBelowFoot = 0.65f;

        [Header("Diagnostics")]
        [SerializeField] private bool debugFootsteps = false;
        [SerializeField] private bool drawFootGizmos = true;

        private Vector3 lastPosition;
        private float traveled;
        private bool nextIsLeft = true;
        private bool initialized;
        private FootTrailEffect runtimeLeft, runtimeRight, leftSource, rightSource;
        private bool ownsLeft, ownsRight, effectsInitialized;

        public bool IsMoving { get; private set; }
        public FootTrailEffect LeftRuntimeEffect => runtimeLeft;
        public FootTrailEffect RightRuntimeEffect => runtimeRight;
        private Transform MoveTransform => movementSource != null ? movementSource : transform;

        private void Awake()
        {
            InitializeEffects();
        }

        private void OnEnable()
        {
            InitializeEffects();
            SyncFootEmitters();
            ResetTracking();
        }

        /// <summary>Accept either a prefab asset or an existing effect. Never move or emit from a prefab asset.</summary>
        public void InitializeEffects()
        {
            FindHumanoidBonesIfNeeded();
            ResolveEffect(leftEffect, ref runtimeLeft, ref leftSource, ref ownsLeft, "Left", null);
            ResolveEffect(rightEffect, ref runtimeRight, ref rightSource, ref ownsRight, "Right", runtimeLeft);
            effectsInitialized = true;
            SyncFootEmitters();
        }

        private void ResolveEffect(FootTrailEffect source, ref FootTrailEffect runtime,
            ref FootTrailEffect previousSource, ref bool owned, string side, FootTrailEffect other)
        {
            if (previousSource == source && runtime != null && runtime != other) return;
            ReleaseEffect(ref runtime, ref owned);
            previousSource = source;
            if (source == null) return;
            // Prefab assets have no loaded scene. A single scene instance assigned to both feet
            // also needs a second emitter, otherwise the right foot moves the left emitter.
            owned = !source.gameObject.scene.IsValid() || !source.gameObject.scene.isLoaded || source == other;
            runtime = owned ? Instantiate(source, transform, false) : source;
            if (!owned) return;
            runtime.name = source.name + " (" + side + " Foot)";
            runtime.gameObject.SetActive(true);
            foreach (var particles in runtime.GetComponentsInChildren<ParticleSystem>(true))
            {
                particles.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
                var main = particles.main;
                main.playOnAwake = false;
                main.simulationSpace = ParticleSystemSimulationSpace.World;
            }
        }

        private static void ReleaseEffect(ref FootTrailEffect effect, ref bool owned)
        {
            if (owned && effect != null)
            {
                effect.StopAndClear();
                if (Application.isPlaying) Destroy(effect.gameObject);
                else DestroyImmediate(effect.gameObject);
            }
            effect = null;
            owned = false;
        }

        private void OnDisable()
        {
            if (ownsLeft && runtimeLeft != null) runtimeLeft.StopAndClear();
            if (ownsRight && runtimeRight != null) runtimeRight.StopAndClear();
            initialized = false;
            IsMoving = false;
        }

        private void OnDestroy()
        {
            ReleaseEffect(ref runtimeLeft, ref ownsLeft);
            ReleaseEffect(ref runtimeRight, ref ownsRight);
        }

        private void Start()
        {
            if (followFootBones && (leftFootBone == null || rightFootBone == null))
                Debug.LogWarning(
                    "Foot Trails V5: missing Left/Right Foot Bone. Assign both animated foot bones " +
                    "in FootTrailController (or use a Humanoid Animator with Auto Find enabled).", this);
        }

        [ContextMenu("Auto-assign Humanoid Foot Bones")]
        private void FindHumanoidBonesIfNeeded()
        {
            if (!autoFindHumanoidBones) return;
            bool needsLeft = NeedsAnimatedFoot(leftFootBone);
            bool needsRight = NeedsAnimatedFoot(rightFootBone);
            if (!needsLeft && !needsRight) return;

            Animator animator = GetComponentInChildren<Animator>();
            if (animator == null || !animator.isHuman) return;

            if (needsLeft)
                leftFootBone = animator.GetBoneTransform(HumanBodyBones.LeftFoot);
            if (needsRight)
                rightFootBone = animator.GetBoneTransform(HumanBodyBones.RightFoot);
        }

        private static bool NeedsAnimatedFoot(Transform bone) => bone == null ||
            bone.name.StartsWith("ik_foot", System.StringComparison.OrdinalIgnoreCase);

        public void ResetTracking()
        {
            lastPosition = MoveTransform.position;
            traveled = 0f;
            nextIsLeft = true;
            IsMoving = false;
            initialized = true;
        }

        private void LateUpdate() => Tick(Time.deltaTime);

        // Evaluate after the Animator and scripted battle-entry movement have updated this frame.
        public void Tick(float dt)
        {
            if (!effectsInitialized) InitializeEffects();
            SyncFootEmitters();
            Vector3 current = MoveTransform.position;
            if (!initialized)
            {
                ResetTracking();
                return;
            }

            Vector3 delta = current - lastPosition;
            lastPosition = current;
            delta.y = 0f;
            float distance = delta.magnitude;

            if (!automaticFootsteps || dt <= 0f)
            {
                IsMoving = false;
                traveled = 0f;
                return;
            }

            if (distance > teleportThreshold)
            {
                IsMoving = false;
                traveled = 0f;
                if (debugFootsteps)
                    Debug.Log("Foot Trails: ignored teleport.", this);
                return;
            }

            float speed = distance / dt;
            IsMoving = distance > 0.00001f && speed >= minimumSpeed;
            if (!IsMoving)
            {
                traveled = 0f;
                return;
            }

            traveled += distance;
            int steps = 0;
            while (traveled >= metersPerStep && steps < maximumStepsPerFrame)
            {
                traveled -= metersPerStep;
                if (nextIsLeft) OnLeftFootstep();
                else OnRightFootstep();
                nextIsLeft = !nextIsLeft;
                steps++;
            }
        }

        private void SyncFootEmitters()
        {
            if (!followFootBones) return;
            Follow(runtimeLeft, leftFootBone, leftFootWorldOffset);
            Follow(runtimeRight, rightFootBone, rightFootWorldOffset);
        }

        private void Follow(FootTrailEffect effect, Transform footBone, Vector3 offset)
        {
            if (effect == null || footBone == null) return;
            if (effect.transform == footBone) return;

            // Explicit world position: works whether the prefab is in the Scene root,
            // under Player, or already parented to an armature bone.
            effect.transform.position = footBone.position + offset;
            if (keepEmittersUpright)
                effect.transform.rotation = Quaternion.identity;
        }

        // Can also be called from Animation Events when Automatic Footsteps is OFF.
        public void OnLeftFootstep()
        {
            if (!effectsInitialized) InitializeEffects();
            EmitFootstep(runtimeLeft, leftFootBone, leftFootWorldOffset, "LEFT");
        }

        public void OnRightFootstep()
        {
            if (!effectsInitialized) InitializeEffects();
            EmitFootstep(runtimeRight, rightFootBone, rightFootWorldOffset, "RIGHT");
        }

        private void EmitFootstep(FootTrailEffect effect, Transform bone,
            Vector3 offset, string side)
        {
            if (effect == null)
            {
                if (debugFootsteps)
                    Debug.LogWarning("Foot Trails: " + side + " Effect is not assigned.", this);
                return;
            }

            if (!effect.gameObject.activeInHierarchy)
            {
                if (debugFootsteps)
                    Debug.LogWarning("Foot Trails: " + side + " effect is inactive.", effect);
                return;
            }

            // Always snap to the latest bone position before emitting the burst.
            if (followFootBones) Follow(effect, bone, offset);

            if (requireGroundContact)
            {
                Vector3 origin = effect.transform.position +
                    Vector3.up * probeStartAboveFoot;
                float length = probeStartAboveFoot + probeDistanceBelowFoot;
                if (!Physics.Raycast(origin, Vector3.down, length,
                    groundLayers, QueryTriggerInteraction.Ignore))
                {
                    if (debugFootsteps)
                        Debug.Log("Foot Trails: " + side + " skipped (ground miss).", this);
                    return;
                }
            }

            effect.EmitOnce();
            if (debugFootsteps)
                Debug.Log("Foot Trails: " + side + " BURST at " +
                    effect.transform.position, effect);
        }

        [ContextMenu("TEST: Emit Left Burst (Play Mode)")]
        private void TestLeft()
        {
            if (Application.isPlaying) OnLeftFootstep();
            else Debug.LogWarning("Enter Play Mode to test.", this);
        }

        [ContextMenu("TEST: Emit Right Burst (Play Mode)")]
        private void TestRight()
        {
            if (Application.isPlaying) OnRightFootstep();
            else Debug.LogWarning("Enter Play Mode to test.", this);
        }

        private void OnDrawGizmosSelected()
        {
            if (!drawFootGizmos) return;
            if (leftFootBone != null)
            {
                Gizmos.color = Color.cyan;
                Gizmos.DrawWireSphere(leftFootBone.position + leftFootWorldOffset, 0.06f);
            }
            if (rightFootBone != null)
            {
                Gizmos.color = Color.yellow;
                Gizmos.DrawWireSphere(rightFootBone.position + rightFootWorldOffset, 0.06f);
            }
        }
    }
}
